"use client"
import { type PropsWithChildren, useState } from "react"
import { AppNavbar } from "@/components/blocks/landing-page-01/components/app-navbar"
import { NavbarControl, type Values } from "@/components/blocks/landing-page-01/components/navbar-control"
import { NavbarInset, NavbarProvider } from "@/components/ui/navbar"

export default function Layout({ children }: PropsWithChildren) {
  // Remove this on Production, the Layout should be Server Component
  const [options, setOptions] = useState<Values>({
    variant: "navbar",
    sticky: false,
    fluid: false,
    container: false
  })
  return (
    <NavbarProvider>
      {/*Remove this on Production, the Layout should be Server Component*/}
      <NavbarControl onChange={setOptions} value={options} />
      <AppNavbar {...options} />
      <NavbarInset className={options.sticky ? "*:last:min-h-[200vh]" : ""}>{children}</NavbarInset>
    </NavbarProvider>
  )
}

"use client"

import type { ComponentPropsWithoutRef } from "react"
import type { NavItem } from "./data"
import { Navbar } from "@/components/ui/navbar"

export function NavSecondary({
  items,
  ...props
}: {
  items: NavItem[]
} & ComponentPropsWithoutRef<typeof Navbar.Group>) {
  return (
    <Navbar.Group {...props}>
      <Navbar.GroupContent>
        <Navbar.Menu>
          {items.map((item) => (
            <Navbar.MenuItem key={item.title}>
              <Navbar.MenuButton href={item.url} isActive={item.isActive}>
                {item.icon && <item.icon />}
                <span>{item.title}</span>
              </Navbar.MenuButton>
            </Navbar.MenuItem>
          ))}
        </Navbar.Menu>
      </Navbar.GroupContent>
    </Navbar.Group>
  )
}

